function StatementPage({customer=false,parties,tx}){
 const [party,setParty]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[view,setView]=useState('all');
 const paymentKind=t=>customer?['customer_payment','system_payment'].includes(t.kind):t.kind==='supplier_payment';
 const charge=t=>customer&&paymentKind(t)&&Number(t.total)<0;
 const movementLabel=t=>charge(t)?({charge_extra_expense:'مصروف إضافي',charge_old_balance:'حساب قديم',charge_other:'إضافة أخرى'}[t.mode]||'إضافة على الحساب'):paymentKind(t)?'تسديد':customer?(t.kind==='system'?'بيع منظومة':'فاتورة بيع'):'فاتورة شراء';
 const allowed=customer?['sale','system','customer_payment','system_payment']:['purchase','supplier_payment'];
 const base=tx.filter(t=>t.party===party&&allowed.includes(t.kind)).filter(t=>(!from||t.date.slice(0,10)>=from)&&(!to||t.date.slice(0,10)<=to)).sort((a,b)=>new Date(a.date)-new Date(b.date));
 let running=0;const all=base.map(t=>{running+=paymentKind(t)?-Number(t.total||0):Number(t.total||0);return {...t,payment:paymentKind(t),charge:charge(t),balance:running}});
 const data=all.filter(t=>view==='all'||(view==='payments'?t.payment:!t.payment));const finalBalance=all.length?all[all.length-1].balance:0;
 const text=()=>data.map(t=>new Date(t.date).toLocaleDateString('ar-IQ')+' | '+movementLabel(t)+' | '+fmt(Math.abs(t.total))+' د.ع'+(t.notes?' | '+t.notes:'')).join('\n');
 const statementHtml=()=>{const rows=data.map(t=>'<tr><td>'+new Date(t.date).toLocaleDateString('ar-IQ')+'</td><td>'+movementLabel(t)+'</td><td>'+(t.charge?'+ ':t.payment?'− ':'')+fmt(Math.abs(t.total))+'</td><td><b>'+fmt(t.balance)+'</b></td><td>'+(t.notes||'')+'</td></tr>').join('');const body='<div class="meta"><div><b>الحساب:</b> '+party+'</div><div><b>الفترة:</b> '+(from||'البداية')+' — '+(to||'اليوم')+'</div></div><table><thead><tr><th>التاريخ</th><th>البيان</th><th>المبلغ د.ع</th><th>الرصيد بعد الحركة</th><th>الملاحظات</th></tr></thead><tbody>'+rows+'</tbody></table>';return a4(customer?'كشف حساب عميل':'كشف حساب مورد',body,fmt(finalBalance)+' د.ع',party)};
 const preview=()=>openA4(statementHtml());const share=async()=>{const x='كشف حساب '+party+'\n'+text()+'\nالرصيد النهائي: '+fmt(finalBalance)+' د.ع';await shareA4('كشف-حساب-'+party,x,statementHtml())};
 return <div className="statement"><div className="card form"><PartySearch rows={parties} value={party} onChange={setParty} placeholder={customer?'ابحث عن الزبون بالاسم أو الهاتف…':'ابحث عن المورد…'}/><div className="dateRange"><label>من<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>إلى<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div><div className="statementTabs"><button type="button" className={view==='all'?'active':''} onClick={()=>setView('all')}>الكشف الرئيسي</button><button type="button" className={view==='invoices'?'active':''} onClick={()=>setView('invoices')}>{customer?'المبيعات':'المشتريات'}</button><button type="button" className={view==='payments'?'active':''} onClick={()=>setView('payments')}>التسديدات والحركات</button></div></div>{party&&<><div className="statementTable"><div className="statementRow running head"><b>التاريخ</b><b>البيان</b><b>المبلغ</b><b>الرصيد بعد الحركة</b><b>الملاحظات</b></div>{data.length?data.map(t=><div className={'statementRow running '+(t.charge?'chargeRow':'')} key={t.id}><span>{new Date(t.date).toLocaleDateString('ar-IQ')}</span><span>{movementLabel(t)}</span><b>{t.charge?'+ ':t.payment?'− ':''}{fmt(Math.abs(t.total))} د.ع</b><strong className="runningBalance">{fmt(t.balance)} د.ع</strong><span className="statementNote">{t.notes||''}</span></div>):<div className="empty">لا توجد حركات ضمن الفترة</div>}</div><div className="statementBalance"><span>الرصيد النهائي</span><b>{fmt(finalBalance)} د.ع</b></div><div className="invoiceActions"><button onClick={preview}>معاينة A4</button><button onClick={share}>مشاركة</button><button className="saveInvoice" onClick={()=>saveA4(statementHtml(),'كشف-حساب-'+party)}>حفظ في الجهاز</button></div></>}</div>;
}

function SystemSale({products,customers,installers=[],onSave}){
 const [saving,setSaving]=useState(false);
 const [items,setItems]=useState([]),[q,setQ]=useState(''),[party,setParty]=useState(''),[expenses,setExpenses]=useState(''),[salePrice,setSalePrice]=useState(''),[notes,setNotes]=useState(''),[installerId,setInstallerId]=useState(''),[scheduleEnabled,setScheduleEnabled]=useState(false),[installDate,setInstallDate]=useState(''),[installTime,setInstallTime]=useState(''),[address,setAddress]=useState('');
 const m=q?products.filter(p=>(p.name+' '+p.code+' '+(p.brand||'')+' '+(p.category||'')).toLowerCase().includes(q.toLowerCase())).slice(0,12):[];
 const cost=items.reduce((a,i)=>a+(+i.qty||0)*(+i.cost||0),0),profit=(+salePrice||0)-cost-(+expenses||0);
 const add=p=>{if(!items.some(i=>i.id===p.id))setItems([...items,{...p,availableQty:+p.qty||0,qty:''}]);setQ('')};
 const installer=installers.find(u=>String(u.id)===String(installerId));
 const clean=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const appointment=scheduleEnabled&&installDate&&installTime?new Date(installDate+'T'+installTime).toLocaleString('ar-IQ',{dateStyle:'full',timeStyle:'short'}):'يحدد لاحقاً';
 const doc=(customerCopy=true)=>{
  const rows=items.map(i=>'<tr><td>'+clean(i.name)+'<br><small>'+clean(i.brand||'')+' • '+clean(i.category||'')+'</small></td><td>'+fmt(i.qty)+'</td>'+(customerCopy?'':'<td>'+fmt(+i.cost||0)+' د.ع</td><td>'+fmt((+i.qty||0)*(+i.cost||0))+' د.ع</td>')+'</tr>').join('');
  const receiptStyle='<style>.systemReceipt{font-size:14px}.systemReceipt .receiptInfo{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}.systemReceipt .receiptInfo div{background:#f1f8f6;border:1px solid #cfe2dc;border-radius:10px;padding:12px;line-height:1.8}.systemReceipt table{font-size:14px}.systemReceipt th,.systemReceipt td{padding:13px 8px}.systemReceipt .priceBox{margin-top:16px;padding:15px;border-radius:12px;background:#e7f6f1;border:1px solid #bfdfd4;font-size:17px;display:flex;justify-content:space-between;gap:10px}@media screen and (max-width:700px){html,body{font-size:16px!important}.sheet{padding:18px!important}.systemReceipt{font-size:16px}.systemReceipt .receiptInfo{grid-template-columns:1fr}.systemReceipt table{font-size:15px}.systemReceipt th,.systemReceipt td{font-size:14px!important;padding:14px 7px!important}.head{align-items:start!important}.brand h1{font-size:21px!important}.brand p,.doc small{font-size:13px!important}.doc h2{font-size:18px!important}.total{font-size:18px!important;padding:15px!important}}@media print{.systemReceipt,.systemReceipt table{font-size:13px}.systemReceipt th,.systemReceipt td{font-size:12px!important}}</style>';
  const info='<div class="receiptInfo"><div><b>العميل:</b> '+clean(party||'نقدي')+'</div><div><b>التاريخ:</b> '+new Date().toLocaleDateString('ar-IQ')+'</div><div><b>مهندس التنصيب:</b> '+clean(installer?.display_name||installer?.username||'غير محدد')+'</div><div><b>موعد التنصيب:</b> '+clean(appointment)+'</div>'+(address?'<div style="grid-column:1/-1"><b>عنوان التنصيب:</b> '+clean(address)+'</div>':'')+'</div>';
  const headings=customerCopy?'<th>المادة</th><th>العدد</th>':'<th>المادة</th><th>العدد</th><th>كلفة الوحدة</th><th>الكلفة الكلية</th>';
  const amount=customerCopy?Number(salePrice||0):cost;
  const priceLabel=customerCopy?'سعر المنظومة':'كلفة المواد';
  const body=receiptStyle+'<div class="systemReceipt">'+info+'<table><thead><tr>'+headings+'</tr></thead><tbody>'+rows+'</tbody></table>'+(notes?'<div class="notes"><b>ملاحظات:</b> '+clean(notes)+'</div>':'')+'<div class="priceBox"><span>'+priceLabel+'</span><b>'+fmt(amount)+' د.ع</b></div></div>';
  return a4(customerCopy?'فاتورة بيع منظومة':'وصل مخزني - منظومة',body,fmt(amount)+' د.ع',customerCopy?'نسخة العميل':'نسخة المخزن');
 };
 const share=async(customerCopy)=>shareA4(customerCopy?'وصل-منظومة-للعميل':'وصل-منظومة-مخزني',(customerCopy?'وصل العميل':'وصل مخزني')+' - '+(party||'')+'\n'+items.map(i=>i.name+' × '+i.qty).join('\n')+(customerCopy?'\nالسعر: '+fmt(salePrice)+' د.ع':'\nكلفة المواد: '+fmt(cost)+' د.ع'),doc(customerCopy));
 return <div className="invoice systemSale">
  <PartySearch rows={customers} value={party} onChange={setParty}/>
  <div className="requiredField"><span>مهندس التنصيب <b>إجباري</b></span><select required value={installerId} onChange={e=>setInstallerId(e.target.value)}><option value="">اختر مهندس التنصيب</option>{installers.map(u=><option key={u.id} value={u.id}>{u.display_name||u.username}</option>)}</select>{!installers.length&&<small>لا يوجد مهندس فعّال. أضف مستخدماً بنوع مهندس تنصيب أولاً.</small>}</div>
  <label className="scheduleToggle"><input type="checkbox" checked={scheduleEnabled} onChange={e=>{setScheduleEnabled(e.target.checked);if(!e.target.checked){setInstallDate('');setInstallTime('')}}}/><span><b>تحديد موعد التنصيب</b><small>اختياري — يمكن تحديده لاحقاً</small></span></label>
  {scheduleEnabled&&<div className="dateRange optionalSchedule"><label>اليوم<input required type="date" value={installDate} onChange={e=>setInstallDate(e.target.value)}/></label><label>الساعة<input required type="time" value={installTime} onChange={e=>setInstallTime(e.target.value)}/></label></div>}
  <input value={address} onChange={e=>setAddress(e.target.value)} placeholder="عنوان التنصيب"/>
  <div className="searchBox"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="🔎 ابحث بالاسم أو البراند أو الصنف"/>{m.length>0&&<div className="matches">{m.map(i=><button key={i.id} onClick={()=>add(i)}><b>{i.name}</b><small>{i.brand||'بدون براند'} • المتوفر {fmt(+i.qty||0)} • الكلفة {fmt(+i.cost||0)} د.ع</small></button>)}</div>}</div>
  {items.map(i=>{const overQty=(+i.qty||0)>(+i.availableQty||0);return <div className={'invoiceLine systemLine'+(overQty?' quantityOver':'')} key={i.id}><div className="lineName"><div><b>{i.name}</b><small>{i.brand||''} • {i.category||''}</small></div><button onClick={()=>setItems(items.filter(j=>j.id!==i.id))}>×</button></div><label>العدد<input type="number" min="0.01" max={i.availableQty} step="0.01" value={i.qty} onChange={e=>setItems(items.map(j=>j.id===i.id?{...j,qty:e.target.value}:j))}/></label><div className="systemCostLine"><span className="availableCost">المتوفر بالمخزن <b>{fmt(i.availableQty)}</b></span><span>كلفة الوحدة <b>{fmt(+i.cost||0)} د.ع</b></span><span>كلفة الكمية <b>{fmt((+i.qty||0)*(+i.cost||0))} د.ع</b></span></div>{overQty&&<small className="quantityWarning">الكمية المطلوبة أكبر من الموجود بالمخزن</small>}</div>})}
  <input inputMode="numeric" placeholder="المصاريف الإضافية (اختياري)" value={moneyValue(expenses)} onChange={e=>setExpenses(rawMoney(e.target.value))}/><input inputMode="numeric" placeholder="سعر بيع المنظومة بالدينار" value={moneyValue(salePrice)} onChange={e=>setSalePrice(rawMoney(e.target.value))}/><textarea placeholder="ملاحظات الوصل" value={notes} onChange={e=>setNotes(e.target.value)}/>
  <div className="systemTotals"><div>كلفة المواد <b>{fmt(cost)} د.ع</b></div><div>المصاريف <b>{fmt(expenses||0)} د.ع</b></div><div>الكلفة الكلية <b>{fmt(cost+(+expenses||0))} د.ع</b></div><div className={profit>=0?'profitGood':'profitBad'}>الربح الصافي <b>{salePrice?fmt(profit)+' د.ع':'—'}</b></div></div>
  <div className="receiptCopies"><button onClick={()=>openA4(doc(true))}>معاينة وصل العميل</button><button onClick={()=>openA4(doc(false))}>معاينة النسخة المخزنية</button><button onClick={()=>saveA4(doc(true),'فاتورة-منظومة-'+(party||'عميل'))}>PDF / حفظ العميل</button><button onClick={()=>saveA4(doc(false),'وصل-منظومة-مخزني')}>PDF / حفظ المخزن</button><button onClick={()=>share(true)}>مشاركة للعميل</button><button onClick={()=>share(false)}>مشاركة للمخزن</button></div>
  <button className="primaryWide" disabled={saving} onClick={async()=>{if(saving)return;if(!party)return alert('اختر العميل');if(!installerId)return alert('اختيار مهندس التنصيب إجباري');if(!address.trim())return alert('اكتب عنوان التنصيب');if(scheduleEnabled&&(!installDate||!installTime))return alert('حدد يوم وساعة الموعد أو ألغِ خيار تحديد الموعد');const validation=invoiceError(items.map(i=>({...i,price:0})),products,'system');if(validation)return alert(validation);if(!Number.isFinite(Number(salePrice))||Number(salePrice)<=0||!Number.isFinite(Number(expenses||0))||Number(expenses||0)<0)return alert('أدخل سعر البيع والمصاريف بصورة صحيحة');setSaving(true);try{const ok=await onSave({items:items.map(i=>({...i,qty:+i.qty||0})),total:+salePrice,expenses:+expenses||0,cost,profit,currency:'IQD',party,notes,cash:true,installerId,installDate:scheduleEnabled?installDate:'',installTime:scheduleEnabled?installTime:'',customerAddress:address,customerPhone:customers.find(c=>c.name===party)?.phone||'',installationStatus:'pending'});if(!ok)return;setItems([]);setParty('');setInstallerId('');setScheduleEnabled(false);setInstallDate('');setInstallTime('');setAddress('');setSalePrice('');setExpenses('');setNotes('');alert('تم حفظ المنظومة وإسناد مهمة التنصيب للمهندس')}finally{setSaving(false)}}}>{saving?'جاري الحفظ…':'حفظ المنظومة وإسناد التنصيب'}</button>
 </div>;
}

function StockReport({products}){const [cost,setCost]=useState(true),[query,setQuery]=useState(''),[brand,setBrand]=useState(''),[category,setCategory]=useState('');const available=products.filter(p=>(+p.qty||0)>0&&(!brand||p.brand===brand)&&(!category||p.category===category)&&[p.name,p.code,p.brand,p.category].join(' ').toLowerCase().includes(query.trim().toLowerCase()));const total=available.reduce((a,p)=>a+p.qty*p.cost,0);const makeText=()=>available.map(p=>p.name+' | '+p.qty+(cost?' | '+p.cost+' د.ع | '+fmt((+p.qty||0)*(+p.cost||0))+' د.ع':'')).join('\n')+(cost?'\nالمجموع الكلي: '+fmt(total)+' د.ع':'');const stockHtml=()=>{const rows=available.map(p=>'<tr><td>'+p.name+'<br><small>'+(p.brand||'')+' '+(p.category||'')+'</small></td><td>'+(p.qty||'')+'</td>'+(cost?'<td>'+Number(p.cost||0).toLocaleString()+'</td><td>'+((+p.qty||0)*(+p.cost||0)).toLocaleString()+'</td>':'')+'</tr>').join('');const body='<table><thead><tr><th>المادة</th><th>العدد</th>'+(cost?'<th>الكلفة د.ع</th><th>المجموع د.ع</th>':'')+'</tr></thead><tbody>'+rows+'</tbody></table>';return a4('كشف المخزون',body,cost?total.toLocaleString()+' د.ع':'',new Date().toLocaleDateString('ar-IQ'))}; const preview=()=>openA4(stockHtml());const share=async()=>{const text='مخزون عبدالرحمن سولار\n'+makeText();await shareA4('كشف-المخزون',text,stockHtml())};return <div><div className="reportFilters"><input aria-label="بحث المخزون" placeholder="ابحث بالاسم أو الكود…" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="البراند" value={brand} onChange={e=>setBrand(e.target.value)}><option value="">كل البراندات</option>{[...new Set(products.map(p=>p.brand).filter(Boolean))].map(b=><option key={b}>{b}</option>)}</select><select aria-label="الصنف" value={category} onChange={e=>setCategory(e.target.value)}><option value="">كل الأصناف</option>{[...new Set(products.map(p=>p.category).filter(Boolean))].map(c=><option key={c}>{c}</option>)}</select><small>{available.length} مادة متوفرة ضمن الفلتر</small></div><div className="reportOptions"><label><input type="checkbox" checked={cost} onChange={e=>setCost(e.target.checked)}/> مع الكلفة</label></div><div className={"stockTable"+(cost?"":" unpriced")}><div className="stockRow head"><b>المادة</b><b>العدد</b>{cost&&<><b>السعر</b><b>المجموع</b></>}</div>{available.map(p=><div className="stockRow" key={p.id}><span className="stockMaterial"><b>{p.name}</b><small>{p.brand||"بدون براند"} • {p.category||"بدون صنف"}</small></span><span>{p.qty}</span>{cost&&<><span>{fmt(p.cost)} د.ع</span><span>{fmt((+p.qty||0)*(+p.cost||0))} د.ع</span></>}</div>)}</div>{cost&&<div className="grandTotal"><span>المجموع الكلي</span><b>{fmt(total)} د.ع</b></div>}<div className="invoiceActions"><button onClick={preview}>معاينة</button><button onClick={()=>saveA4(stockHtml(),'كشف-المخزون')}>حفظ في الجهاز</button><button className="saveInvoice" onClick={share}>مشاركة</button></div></div>}
